// Original Elyndra command atlas: one shared visual vocabulary for every entry point.
export const COMMAND_ICONS={bag:0,attributes:1,skills:2,map:3,wings:4,aura:5,pet:6,mount:7,forge:8,runes:9,quest:10,boss:11,shop:12,ranking:13,settings:14,return:15};
export function commandIcon(key,extra=''){const i=COMMAND_ICONS[key]??14;return `<span class="commandIcon ${extra}" aria-hidden="true" style="--ix:${i%4};--iy:${Math.floor(i/4)}"></span>`;}
const tile=(id,key,title,detail='')=>`<button id="${id}" class="commandTile">${commandIcon(key)}<b>${title}</b>${detail?`<small>${detail}</small>`:''}</button>`;
export function commandDeck(p,quality){return `<div class="commandDeck"><div class="deckIdentity"><span class="deckSigil">E</span><div><strong>${p.name.replace(/[<>&"']/g,'')}</strong><small>NV${p.level} · ${p.testMode?'LABORATÓRIO':'CAMPANHA'}</small></div></div><h3>PERSONAGEM</h3><div class="commandTiles">${tile('bagMenu','bag','Equipamentos','Mochila e peças')}${tile('statsMenuButton','attributes','Atributos','FOR · INT · DES')}${tile('bookMenuButton','skills','Habilidades','Ativas e passivas')}${tile('wingsMenuButton','wings','Relíquias','Asas e aura')}${tile('companionsMenu','pet','Companheiros','Pets · montarias · μ')}${tile('allItemsButton','forge','Forja','Receitas e catálogo')}</div><h3>MUNDO</h3><div class="commandTiles">${tile('atlasButton','map','Atlas','Regiões e DGs')}${tile('journalMenu','quest','Jornada','Capítulos e objetivos')}${tile('bossMenuButton','boss','Chefes','Mundiais e cataclismos')}${tile('rankingMenuButton','ranking','Ranking','Poder e vitórias')}${tile('cashMenuButton','shop','Empório','Materiais e estilos')}${tile('visualGallery','aura','Arena de skills','Alvo de treino')}</div><h3>SISTEMA</h3><div class="commandTiles systemTiles">${tile('saveNow','runes','Salvar','Neste dispositivo')}${tile('controls','settings','Controles','Como jogar')}${tile('qualityButton','settings','Desempenho',quality==='balanced'?'Equilibrado':'Economia')}${tile('classButton','skills','Outra classe','Nova seleção')}${tile('labButton','attributes','Laboratório','Atalhos Nv250')}${tile('leaveWorld','return','Tela inicial','Preserva o save')}${p.zone==='dungeon'?tile('leaveDungeon','return','Sair da DG','Ponto seguro'):''}${tile('futureFeatures','map','Sobre a alpha','Sistemas e limites')}</div><p class="deckFootnote">Jogo solo · pausa enquanto este menu estiver aberto. Compras usam cash de teste. Seu progresso fica neste navegador.</p></div>`;}
